AREAS=[
 {'id':'moo','title':'Multi-objective Learning','type':'Competing objectives','question':'Cover the range of useful trade-offs.','description':'Equal steps in a preference weight can leave gaps on the Pareto front. I study how the front’s geometry can guide the choice of weights.','papers':['surf']},
 {'id':'bilevel','title':'Bilevel Optimization','type':'Nested decisions','question':'Optimize a decision through another problem.','description':'In bilevel optimization, an outer decision changes an optimized inner response. I study how curvature, update rules, and moving constraints affect the cost of learning.','papers':['efficient-penalty','pbgd-free','smoothness','blocc']},
 {'id':'applications','title':'Applications','type':'Learning & behavior','question':'Speech models and LLM agents.','description':'My application work develops training targets for speech models and studies the timing and memory of LLM agents’ decisions.','papers':['retailagent','birq']}
]
