def chronological_papers():
 priorities=CURATION.get('display_priority',[])
 return sorted(PAPERS,key=lambda p:(p['slug'] in priorities,p['year'],CURATION['release_months'][p['slug']]),reverse=True)
def opening_visual(area):
 if area=='moo':
  # Analytic convex loss front with nonzero endpoint slopes; displayed as rewards.
  a=.5;k=5.;A=(1-a)*k/(1-math.exp(-k))
  loss=lambda z:a*(1-z)+(1-a)*(math.exp(-k*z)-math.exp(-k))/(1-math.exp(-k))
  slope=lambda z:a+A*math.exp(-k*z)
  w_lo=slope(1)/(1+slope(1));w_hi=slope(0)/(1+slope(0))
  def solve(w):
   if w<=w_lo:return 1.
   if w>=w_hi:return 0.
   return min(1.,max(0.,-math.log((w/(1-w)-a)/A)/k))
  xy=lambda z:(90+280*(1-z),305-280*(1-loss(z)))
  points=' '.join(f'{x:.2f},{y:.2f}' for x,y in [xy(i/200) for i in range(201)])
  dots=''
  for i in range(9):
   z=solve(w_hi-i*(w_hi-w_lo)/8);x,y=xy(z)
   dots+=f'<circle data-front-point="{i}" cx="{x:.2f}" cy="{y:.2f}" r="{8 if i==4 else 5.5}" role="button" tabindex="{0 if i==4 else -1}" aria-pressed="{str(i==4).lower()}" aria-label="Candidate {i+1}: quality {1-z:.2f}, faithfulness {1-loss(z):.2f}"/>'
  svg=f'<svg class="opening-plot" viewBox="0 0 460 360" role="group" aria-label="Illustrative summarizer trade-offs: higher summary quality and faithfulness scores are better. Select a candidate point or use the slider below."><path class="plot-grid" d="M90 25 H370 M90 95 H370 M90 165 H370 M90 235 H370"/><path class="plot-axis" d="M90 17 V305 H388"/><polyline class="front-curve" points="{points}"/>{dots}<text x="230" y="339" text-anchor="middle">Summary quality</text><text x="43" y="165" text-anchor="middle" transform="rotate(-90 43 165)">Faithfulness</text></svg>'
  return '<div class="opening-lab front-lab" data-opening="pareto"><div class="lab-eyebrow">Model trade-offs</div><h3>Same front. Different coverage.</h3><p class="front-context"><strong>Choosing an LLM summarizer.</strong> Each candidate balances summary quality and factual faithfulness. Each point is a different balance between these goals.</p><div class="lab-controls" aria-label="Pareto-front sampling"><button type="button" data-spacing="weights" aria-pressed="true">Equal weights</button><button type="button" data-spacing="arc" aria-pressed="false">Equal distances</button></div>'+svg+'<p class="front-chart-note">Higher scores are better. Click a point to explore a candidate.</p><p class="lab-result" data-spacing-result aria-live="polite">Even weight steps can leave gaps between choices.</p><div class="front-candidate"><div class="lab-range"><label for="front-candidate">Candidate model</label><input id="front-candidate" type="range" min="1" max="9" step="1" value="5"><output for="front-candidate" data-candidate-number>5 of 9</output></div><div class="front-scores" aria-live="polite"><div><span>Summary quality</span><output data-quality-score>0.74</output></div><div><span>Faithfulness</span><output data-faithfulness-score>0.49</output></div></div></div><p class="lab-note">Illustrative normalized scores. SURF studies quality and faithfulness rewards in LLM summarization. <a href="papers/surf/#evidence">See the paper’s application</a>.</p></div>'
 if area=='bilevel':
  return '<div class="opening-lab bakery-lab" data-opening="bakery"><div class="lab-eyebrow">Price and response</div><h3>The bakery sets a price. The customer responds.</h3><div class="bakery-actors"><div class="bakery-actor"><span class="bakery-actor-icon" aria-hidden="true">🧑‍🍳</span><div><strong>Bakery</strong><span>Sets the price, x</span></div></div><div class="bakery-actor customer"><span class="bakery-actor-icon" aria-hidden="true">🛍️</span><div><strong>Customer</strong><span>Chooses bread, y</span></div></div></div><p class="bakery-intro">The shop wants profit. The customer wants a purchase that is worth the price.</p><div class="lab-range"><label for="bakery-price">Bread price, x · dollars per kg</label><input id="bakery-price" type="range" min="1" max="8" step="0.5" value="3"><output for="bakery-price" data-bakery-price>$3.00</output></div><div class="bakery-constraints" role="group" aria-label="Optional bakery constraints"><p>Add optional constraints</p><div class="lab-controls"><button type="button" data-bakery-constraint="budget" aria-pressed="false"><span class="bakery-inline-icon" aria-hidden="true">💳</span>Customer budget: $12</button><button type="button" data-bakery-constraint="stock" aria-pressed="false"><span class="bakery-inline-icon" aria-hidden="true">🥖</span>Available bread: 3 kg</button></div><p class="constraint-status" data-bakery-constraints>No extra constraints.</p></div><div class="bakery-metrics"><div><span><span class="bakery-inline-icon" aria-hidden="true">🥖</span>Customer buys, <var>y</var><sup>*</sup>(<var>x</var>)</span><output data-bakery-quantity>5 kg</output></div><div><span><span class="bakery-inline-icon" aria-hidden="true">💰</span>Bakery profit</span><output data-bakery-profit>$10.00</output></div></div><div class="bakery-plot-tabs" role="tablist" aria-label="Bakery model views" hidden><button type="button" id="bakery-response-tab" role="tab" aria-selected="true" aria-controls="bakery-response-view" data-bakery-view="response">Customer response</button><button type="button" id="bakery-profit-tab" role="tab" aria-selected="false" aria-controls="bakery-profit-view" tabindex="-1" data-bakery-view="profit">Bakery profit</button></div><div id="bakery-response-view" role="tabpanel" aria-labelledby="bakery-response-tab" tabindex="0" data-bakery-panel="response"><figure class="bakery-figure"><figcaption><h4>Customer response <var>y</var><sup>*</sup>(<var>x</var>)</h4><p>How much bread the customer chooses at each price.</p></figcaption><svg class="bakery-plot" viewBox="0 0 420 260" role="img" aria-label="Bread purchases at different prices, showing the customer’s preferred quantity and the quantity allowed by the selected constraints"><g data-bakery-plot></g></svg><div class="bakery-legend"><span>Preferred purchase</span><span>Purchase with selected limits</span></div></figure></div><div id="bakery-profit-view" role="tabpanel" aria-labelledby="bakery-profit-tab" tabindex="0" data-bakery-panel="profit"><figure class="bakery-figure"><figcaption><h4>Bakery profit</h4><p class="bakery-profit-formula">Profit(<var>x</var>, <var>y</var>) = (<var>x</var> − 1)<var>y</var></p><p>The curve shows profit at each price, using the customer’s purchase <span class="bakery-inline-formula"><var>y</var><sup>*</sup>(<var>x</var>)</span>.</p></figcaption><svg class="bakery-plot bakery-profit-plot" viewBox="0 0 420 260" role="img" aria-label="Bakery profit in dollars versus bread price, evaluated at the customer’s purchase at each price"><g data-bakery-profit-base></g><g data-bakery-profit-overlay></g></svg><div class="bakery-profit-legend"><span class="baseline-profit-line">Without extra limits</span><span class="current-profit-line">Profit with selected limits</span><span class="selected-point">Selected price</span></div></figure></div><p class="bakery-result" data-bakery-result aria-live="polite">At $3 per kg, the customer buys 5 kg. The bakery earns $10.</p><p class="lab-note">The bakery chooses x. The customer determines y, so the bakery’s profit follows the response curve.</p><details class="bakery-model"><summary>About this illustrative model</summary><p>Without extra limits, the customer prefers 8 − x kg. This maximizes their modeled satisfaction minus the price paid. Bread costs the shop $1 per kg, so profit is (x − 1)y.</p><p>A budget limits spending: xy ≤ 12. Stock limits the amount bought: y ≤ 3.</p></details></div>'
 return '<div class="opening-lab" data-opening="applications"><div class="lab-eyebrow">Speech and agents</div><div class="lab-controls" aria-label="Application preview"><button type="button" data-application="speech" aria-pressed="true">Speech targets</button><button type="button" data-application="agents" aria-pressed="false">Agent decisions</button></div><div class="application-view" data-application-view="speech"><h3>Learn from the model’s own features.</h3><img class="speech-original" src="assets/paper-figures/birq-figure1.png" width="1938" height="2057" alt="Original BiRQ Figure 1: enhanced targets from intermediate features and anchoring targets from raw input." loading="lazy"><p class="lab-result">Enhanced labels evolve with the encoder; input-based anchors stabilize training.</p><p class="lab-note">Original BiRQ Figure 1. <a href="https://arxiv.org/html/2509.15430v1#S1.F1">Paper source</a></p></div><div class="application-view" data-application-view="agents" hidden><h3>Observe. Decide. Carry state forward.</h3><img class="agents-original" src="assets/paper-figures/retailagent-figure2.png" width="1452" height="708" alt="Original RetailAgent Figure 2 showing observations, self-authored memory, and a frozen LLM’s long-or-flat decisions." loading="lazy"><p class="lab-result">The agent commits to long or flat before the next return is revealed.</p><p class="lab-note">Original RetailAgent Figure 2. <a href="https://arxiv.org/pdf/2608.28399v1#page=3">Paper source</a></p></div></div>'
def original_paper_figure(p,index=0):
 fs=FIGURES.get(p['slug'],[])
 if index>=len(fs):return ''
 f=fs[index];src='../../assets/paper-figures/'+f['file']
 portrait=' portrait' if f.get('portrait') else ''
 return '<figure class="paper-figure'+portrait+'"><div class="figure-heading"><span>From the paper</span><a href="'+e(src)+'" target="_blank" rel="noopener">View full size</a></div><a class="figure-image" href="'+e(src)+'" target="_blank" rel="noopener" aria-label="View full-size '+e(f['label'])+'"><img src="'+e(src)+'" width="'+str(f['width'])+'" height="'+str(f['height'])+'" loading="lazy" decoding="async" alt="'+e(f['alt'])+'"></a><figcaption><strong>'+e(f['label'])+'</strong><p>'+e(f['caption'])+'</p><a href="'+e(f['source'])+'">Original paper source</a></figcaption></figure>'
def publication_preview(p):
 s=p['slug'];original=next((f for f in FIGURES.get(s,[]) if f.get('preview')),None)
 if original:
  portrait=' portrait' if original.get('portrait') else ''
  return '<a class="pub-preview original-preview'+portrait+'" href="papers/'+s+'/#idea" aria-label="'+e(p['short'])+' project page"><div class="preview-image"><img src="assets/paper-figures/'+original['file']+'" width="'+str(original['width'])+'" height="'+str(original['height'])+'" alt="'+e(original['alt'])+'" loading="lazy" decoding="async"></div><span>Original paper · '+e(original['label'].split(' · ')[0])+'</span></a>'
 blue='#354ac6';green='#007c70';gray='#9aa7bd'
 if s=='retailagent':
  # Reported signed estimates and date-bootstrap 95% intervals, Table 1.
  rows=[('Intact',-45.7,-49.4,-41.8,blue),('Global shuffle',-3.5,-5.4,-1.7,gray),('Same-day',-8.7,-10.4,-7.1,green)]
  axis=lambda val:332+3.6*val
  inside='<text x="24" y="30" class="plot-title">Timing alpha</text><text x="24" y="51" class="plot-note">bps per stock-day · 95% CI</text><path d="M332 69 V177" stroke="'+gray+'"/>'
  for i,(label,value,lo,hi,color) in enumerate(rows):
   y=87+36*i;x=axis(value)
   inside+=f'<text x="24" y="{y+5}">{label}</text><rect x="{x:.2f}" y="{y-10}" width="{332-x:.2f}" height="20" rx="2" fill="{color}" opacity=".22"/><path d="M{axis(lo):.2f} {y} H{axis(hi):.2f} M{axis(lo):.2f} {y-5} V{y+5} M{axis(hi):.2f} {y-5} V{y+5}" stroke="{color}" stroke-width="2"/><circle cx="{x:.2f}" cy="{y}" r="4" fill="{color}"/><text x="354" y="{y+5}" text-anchor="end">{value:g}</text>'
  inside+='<text x="152" y="199">−50</text><text x="323" y="199">0</text>'
  # Keep values in a separate right column, so the zero reference remains visible.
  inside=inside.replace('x="354"','x="396"')
  caption='Reported results · Table 1';label='RetailAgent Table 1: intact schedule has −45.7 bps timing alpha, global shuffle −3.5, and same-day shuffle −8.7, with reported 95 percent confidence intervals.'
 else:
  inside='<text x="24" y="30" class="plot-title">Which objective is curved?</text><text x="24" y="51" class="plot-note">Exact quadratic example · γ = 5</text><path d="M48 75 V172 H372" fill="none" stroke="'+gray+'"/>'
  for a,col in [(5.5,blue),(.5,green)]:
   pts=' '.join(f'{48+324*i/100:.2f},{172-88*a*(-1+2*i/100)**2/5.5:.2f}' for i in range(101))
   inside+=f'<polyline points="{pts}" fill="none" stroke="{col}" stroke-width="3"/>'
  inside+='<circle cx="45" cy="203" r="4" fill="'+blue+'"/><text x="56" y="208">Fixed y = 0</text><circle cx="232" cy="203" r="4" fill="'+green+'"/><text x="243" y="208">Minimize over y</text>'
  caption='Quadratic example · joint and reduced';label='Exact quadratic toy: fixing y creates penalty-dependent curvature, while minimizing over y leaves x squared over two. This analytical example compares the two objectives.'
 svg='<svg viewBox="0 0 420 230" role="img" aria-label="'+e(label)+'">'+inside+'</svg>'
 return '<a class="pub-preview" href="papers/'+s+'/" aria-label="'+e(p['short'])+' project page">'+svg+'<span>'+e(caption)+'</span></a>'
def publication_row(p):
 slug=p['slug'];area=AREA_BY_SLUG[slug]
 authors=', '.join('<strong>'+e(n)+'</strong>' if n=='Liuyuan Jiang' else e(n) for n in p['authors'])
 links=f'<a href="{p["paper"]}">Paper</a>'
 if p.get('code'):links+=f'<a href="{p["code"]}">Code</a>'
 links+=f'<a href="papers/{slug}/">Project page</a>'
 if PUBLISH_VIDEOS:links+=f'<a href="videos/{slug}/">Video storyboard</a>'
 venue=e(p['venue']) if p['venue']!='Preprint' else 'arXiv preprint'
 note='<p class="pub-note">'+e(p['venue_note'])+'</p>' if p.get('venue_note') else ''
 return f'<article id="paper-{slug}" class="publication-row {area["id"]}" aria-labelledby="title-{slug}">{publication_preview(p)}<div class="pub-record"><div class="pub-overline"><span>{p["year"]}</span><span class="topic-label">{e(area["title"])}</span></div><h3 id="title-{slug}"><a href="papers/{slug}/">{e(p["title"])}</a></h3><p class="pub-authors">{authors}</p><p class="pub-venue">{venue}{" · "+str(p["year"]) if str(p["year"]) not in p["venue"] else ""}</p>{note}<p class="pub-summary">{e(p["description"])}</p><div class="pub-links">{links}</div></div></article>'
def direction_paper(p):
 c=CURATION['direction_papers'][p['slug']]
