def profile_links():
 return '<div class="profile-links" aria-label="Academic and contact links">'+''.join('<a href="'+e(link['url'])+'">'+e(link['label'])+'</a>' for link in PROFILE['links'])+'</div>'
def home():
 by={p['slug']:p for p in PAPERS};ordered=chronological_papers();rank={p['slug']:i for i,p in enumerate(ordered,1)};tabs='';panels=''
 for i,area in enumerate(AREAS):
  count=len(area['papers']);active=i==0
  tabs+=f'<button type="button" id="direction-tab-{area["id"]}" role="tab" aria-controls="{area["id"]}" aria-selected="{str(active).lower()}" tabindex="{0 if active else -1}" data-direction="{area["id"]}"><span>{e(area["title"])}</span><small>{e(area["type"])}</small></button>'
  paper_links=''.join(direction_paper(by[slug]) for slug in sorted(area['papers'],key=lambda s:rank[s]))
  panels+=f'<section id="{area["id"]}" class="direction-panel {area["id"]}" role="tabpanel" aria-labelledby="direction-tab-{area["id"]}" tabindex="0" {"" if active else "hidden"}><div class="direction-story"><div class="eyebrow">{e(area["type"])}</div><h2>{e(area["question"])}</h2><p class="direction-intro">{concept_prose(area["description"])}</p></div>{opening_visual(area["id"])}<div class="direction-papers">{paper_links}</div></section>'
 rows=''.join(publication_row(p) for p in ordered)
 return head('Liuyuan Jiang | Learning and Decisions','Optimization for multi-objective learning, nested decisions, speech representations, and LLM agents.')+f'<main id="main" class="wrap"><header class="research-intro"><div><div class="eyebrow">Liuyuan Jiang · University of Rochester</div><h1>The geometry of<br><em>learning and decisions.</em></h1></div></header><section class="research-overview" aria-label="Research directions" data-direction-explorer><div class="atlas-intro"><h2>Research directions</h2></div><div class="direction-tabs" role="tablist" aria-label="Research directions">{tabs}</div>{panels}<noscript><style>.direction-panel[hidden]{{display:grid!important}}.direction-tabs{{display:none}}</style></noscript></section><section id="papers" class="publication-collection"><div class="section-top"><h2>Publications &amp; projects</h2></div><div class="publication-list">{rows}</div></section><section id="about" class="about"><div><div class="eyebrow">About</div><h2>Liuyuan Jiang</h2></div><div><p>I am a PhD student in Electrical and Computer Engineering at the University of Rochester, advised by Prof. Lisha Chen. Previously, I was a PhD student at Rensselaer Polytechnic Institute, advised by Prof. Tianyi Chen.</p><p>I study how optimization shapes learning: navigating competing objectives, solving nested problems, and understanding model behavior.</p>{profile_links()}</div></section></main>'+footer()
